import re, subprocess, sys
BASE = "abc123"
FILES = ["testing/test_existing.py","testing/test_added.py"]
F2P = ["testing/test_existing.py::test_hidden_regression"]
P2P = ["testing/test_added.py::test_hidden_new"]
PATCH = "diff --git a/testing/test_existing.py b/testing/test_existing.py\n--- a/testing/test_existing.py\n+++ b/testing/test_existing.py\n@@ -1 +1,2 @@\n import pytest\n+def test_hidden_regression(): assert \"naïve\" == \"naïve\"\ndiff --git a/testing/test_added.py b/testing/test_added.py\nnew file mode 100644\n--- /dev/null\n+++ b/testing/test_added.py\n@@ -0,0 +1 @@\n+def test_hidden_new(): assert 'it''s'\n"
BYTECODE_CLEANUP = "rm -f 'testing/__pycache__/test_existing'.*.pyc; rm -f 'testing/__pycache__/test_added'.*.pyc"

def q(s):
    return "'" + s.replace("'", "'\\''") + "'"

def sh(c, data=None, **kw):
    io = {"input": data} if data is not None else {"stdin": subprocess.DEVNULL}
    return subprocess.run(["bash", "-lc", c], capture_output=True, encoding="utf-8", errors="replace", cwd="/testbed", **io, **kw)

def restore():
    # Each hidden-test file back to the base commit; one the patch added is removed.
    for f in FILES:
        if sh("git cat-file -e %s" % q(BASE + ":" + f)).returncode == 0:
            sh("git checkout -q %s -- %s" % (BASE, q(f)))
        else:
            sh("rm -f -- %s" % q(f))
    if BYTECODE_CLEANUP:
        sh(BYTECODE_CLEANUP)

# Lay the hidden tests over whatever the agent has done.
restore()
applied = sh("git apply --whitespace=nowarn -", data=PATCH)
if applied.returncode != 0:
    restore()
    print("VERIFY: test patch did not apply"); sys.exit(2)

try:
    run = sh("source /opt/miniconda3/bin/activate testbed >/dev/null 2>&1; PYTHONDONTWRITEBYTECODE=1 python -m pytest -rA --tb=short -p no:cacheprovider 'testing/test_existing.py' 'testing/test_added.py' 2>&1", timeout=900)
    log = run.stdout + run.stderr
except subprocess.TimeoutExpired:
    log = "VERIFY: the tests timed out"
restore()

status = {}
for line in log.splitlines():
    m = re.match(r"^(PASSED|FAILED|ERROR)\s+(\S+)", line.strip())
    if m:
        status[m.group(2)] = m.group(1) == "PASSED"

f2p_bad = [t for t in F2P if status.get(t) is not True]
p2p_bad = [t for t in P2P if status.get(t) is not True]
print("VERIFY: F2P %d/%d, P2P %d/%d" % (len(F2P) - len(f2p_bad), len(F2P), len(P2P) - len(p2p_bad), len(P2P)))
if f2p_bad:
    print("still failing: " + ", ".join(f2p_bad[:6]))
if p2p_bad:
    print("regressed: " + ", ".join(p2p_bad[:6]))
if not f2p_bad and not p2p_bad:
    print("ALL REQUIRED TESTS PASS")
    sys.exit(0)
tail = [l for l in log.splitlines() if l.strip()][-12:]
print("\n".join(tail))
sys.exit(1)

